<template><LearnecAppShell role="STUDENT"><section v-if="data" class="assignment-detail" data-assignment-detail><NuxtLink class="back" to="/center/assignments">← 返回作业中心</NuxtLink><header><div><p>综合实训工单</p><h1>{{ data.task.title }}</h1><span>{{ data.task.description }}</span></div><div class="score"><b>{{ data.task.autoScoreWeight }}%</b><small>自动评分</small><b>{{ data.task.manualScoreWeight }}%</b><small>人工评分</small></div></header><div class="guide-card"><h2>工单区块</h2><div v-for="(section,index) in data.sections" :key="section.id" class="section-row"><span>{{ Number(index) + 1 }}</span><div><strong>{{ section.title }}</strong><small>{{ typeLabel(section) }} · {{ section.required ? '必做' : '选做' }}</small></div><b>{{ section.weightPercent }}%</b></div></div><div class="action-bar"><span>{{ data.task.status === 'SUBMITTED' ? '本工单已提交，等待教师批阅。' : '进入后请按左侧指导书依次完成全部必做项。' }}</span><NuxtLink v-if="['IN_PROGRESS','RETURNED'].includes(data.task.status)" class="primary" :to="`/center/tasks/${taskId}/sandbox`">继续实训</NuxtLink><button v-else-if="data.task.status === 'AVAILABLE'" type="button" data-start-task :disabled="starting" @click="startTask">{{ starting ? '正在启动...' : '开始实训' }}</button><NuxtLink v-else-if="data.task.status === 'SUBMITTED'" class="secondary" :to="`/center/tasks/${taskId}/sandbox`">查看提交</NuxtLink></div></section><section v-else class="loading">正在读取指导书...</section></LearnecAppShell></template>
<script setup lang="ts">const route=useRoute(); const taskId=String(route.params.studentTaskId); const starting=ref(false); const {data}=await useFetch<any>(`/api/center/student-tasks/${encodeURIComponent(taskId)}`,{headers:import.meta.server?useRequestHeaders(['cookie']):undefined}); const labels:Record<string,string>={STORE_BASICS:'店铺基础',PRODUCT_MANAGEMENT:'商品管理',STORE_DECORATION:'店铺装修',MARKETING:'营销活动',BUSINESS_ANALYTICS:'经营分析'}; function typeLabel(section:any){return section.sandbox?labels[section.sandbox.sandboxType]??'实操沙盘':section.type==='MEDIA'?'媒体学习':section.type==='QUIZ'?'理论考核':'综合工单'} async function startTask(){starting.value=true;try{await $fetch(`/api/center/student-tasks/${encodeURIComponent(taskId)}/start`,{method:'POST',headers:useCsrfHeaders({'Idempotency-Key':`start-${taskId}`})});await navigateTo(`/center/tasks/${taskId}/sandbox`)}finally{starting.value=false}}</script>
<style scoped>.assignment-detail{max-width:980px;margin:0 auto}.back{display:inline-block;margin-bottom:18px;color:#667085;font-size:13px;text-decoration:none}.assignment-detail>header{display:flex;justify-content:space-between;gap:24px;padding:28px;border:1px solid #e4e8ef;border-radius:8px;background:#fff}.assignment-detail header p{margin:0;color:#1677ff;font-size:12px;font-weight:800}.assignment-detail h1{margin:8px 0;color:#172033;font-size:26px}.assignment-detail header span{color:#667085;font-size:14px;line-height:1.7}.score{display:grid;grid-template-columns:auto auto;gap:2px 8px;align-content:start;padding:14px;background:#f3f7ff;border-radius:6px;white-space:nowrap}.score b{color:#145bc2;font-size:19px}.score small{align-self:center;color:#667085}.guide-card{margin-top:16px;padding:24px;border:1px solid #e4e8ef;border-radius:8px;background:#fff}.guide-card h2{margin:0 0 16px;font-size:18px}.section-row{display:grid;grid-template-columns:28px 1fr auto;gap:12px;align-items:center;padding:13px 0;border-top:1px solid #eaecf0}.section-row>span{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:#eff8ff;color:#145bc2;font-size:12px;font-weight:700}.section-row strong,.section-row small{display:block}.section-row strong{font-size:14px}.section-row small{margin-top:3px;color:#7b8494;font-size:12px}.section-row>b{color:#475467;font-size:13px}.action-bar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:16px;padding:18px 22px;border:1px solid #dbeafe;border-radius:8px;background:#eff6ff;color:#475467;font-size:13px}.action-bar button,.action-bar a{min-height:38px;box-sizing:border-box;padding:0 16px;border:0;border-radius:6px;font-weight:700;text-decoration:none;cursor:pointer}.action-bar button,.primary{display:inline-flex;align-items:center;background:#1677ff;color:#fff}.secondary{display:inline-flex;align-items:center;border:1px solid #1677ff!important;color:#145bc2}.loading{padding:40px;color:#667085;text-align:center}@media(max-width:640px){.assignment-detail>header{flex-direction:column;padding:20px}.score{align-self:start}.action-bar{align-items:flex-start;flex-direction:column}.action-bar button,.action-bar a{width:100%;justify-content:center}}</style>
